package com.neml.badminton.repository;import com.neml.badminton.entity.AuctionConfiguration;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;import java.util.*;
public interface AuctionConfigurationRepository extends JpaRepository<AuctionConfiguration,UUID>{Optional<AuctionConfiguration> findFirstByChampionshipIdOrderByConfigurationVersionDesc(UUID championshipId);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select c from AuctionConfiguration c where c.championship.id=:cid and c.configurationVersion=(select max(x.configurationVersion) from AuctionConfiguration x where x.championship.id=:cid)")Optional<AuctionConfiguration> findLatestForUpdate(@Param("cid")UUID championshipId);}
